SELECT N.DESCRPROD AS PRODUTO, SUM(CASE WHEN DATE_FORMAT(N.DTNEG, '%Y-%m') = :VAR_MES_SELECIONADO AND N.ATUALESTOQUE = 1 THEN N.PESO_ITEM ELSE 0 END) AS QTD_ENTRADA, SUM(CASE WHEN DATE_FORMAT(N.DTNEG, '%Y-%m') = :VAR_MES_SELECIONADO AND N.ATUALESTOQUE = -1 THEN N.PESO_ITEM ELSE 0 END) AS QTD_SAIDA, SUM(CASE WHEN DATE_FORMAT(N.DTNEG, '%Y-%m') = :VAR_MES_SELECIONADO THEN (CASE WHEN N.ATUALESTOQUE = 1 THEN N.PESO_ITEM WHEN N.ATUALESTOQUE = -1 THEN -N.PESO_ITEM ELSE 0 END) ELSE 0 END) AS SALDO_LIQUIDO, SUM(CASE WHEN N.ATUALESTOQUE = 1 THEN N.PESO_ITEM WHEN N.ATUALESTOQUE = -1 THEN -N.PESO_ITEM ELSE 0 END) AS SALDO_REAL, SUM(CASE WHEN N.ATUALESTOQUE = 1 THEN (N.VLRUNIT * N.QTDNEG) WHEN N.ATUALESTOQUE = -1 THEN -(N.VLRUNIT * N.QTDNEG) ELSE 0 END) AS VALOR_TOTAL FROM IMP_NOTAS_ARMAZ N WHERE N.CODPARC = :VAR_PARCEIRO_SELECIONADO GROUP BY N.DESCRPROD HAVING SUM(CASE WHEN DATE_FORMAT(N.DTNEG, '%Y-%m') = :VAR_MES_SELECIONADO THEN 1 ELSE 0 END) > 0 OR ROUND(SUM(CASE WHEN N.ATUALESTOQUE = 1 THEN N.PESO_ITEM WHEN N.ATUALESTOQUE = -1 THEN -N.PESO_ITEM ELSE 0 END), 2) <> 0 ORDER BY SALDO_LIQUIDO DESC, SALDO_REAL DESC